const body = $json.body || $json;

const asText = (key) => {
  const value = body[key];
  return typeof value === 'string' ? value.trim() : '';
};

const toBool = (value) => {
  if (typeof value === 'boolean') return value;
  if (typeof value === 'number') return value === 1;
  if (typeof value !== 'string') return false;
  return ['1', 'true', 'yes', 'on'].includes(value.trim().toLowerCase());
};

const form = {
  name: asText('name'),
  email: asText('email'),
  company: asText('company'),
  website: asText('website'),
  team_size: asText('team_size'),
  current_tools: asText('current_tools'),
  repetitive_process: asText('repetitive_process'),
  admin_time_lost: asText('admin_time_lost'),
  desired_outcome: asText('desired_outcome'),
  contact_consent: toBool(body.contact_consent)
};

const missing = Object.entries(form)
  .filter(([key, value]) => key !== 'contact_consent' && !value)
  .map(([key]) => key);

if (missing.length) {
  throw new Error(`Missing required fields: ${missing.join(', ')}`);
}

if (!form.contact_consent) {
  throw new Error('Contact consent is required');
}

let cleanWebsite = form.website;
if (!/^https?:\/\//i.test(cleanWebsite)) {
  cleanWebsite = `https://${cleanWebsite}`;
}

if (!/^https?:\/\/[^\s]+$/i.test(cleanWebsite)) {
  throw new Error('Website must be a valid URL');
}

const parts = form.name.split(/\s+/).filter(Boolean);
const firstName = parts[0];
const lastName = parts.slice(1).join(' ') || '-';
const receivedAt = new Date().toISOString();
const source = 'riera.co.uk';

const leadDescription = [
  'Paid Automation Audit request',
  '',
  `Team size: ${form.team_size}`,
  `Current tools: ${form.current_tools}`,
  `Most repetitive process: ${form.repetitive_process}`,
  `Estimated admin time lost: ${form.admin_time_lost}`,
  `Desired outcome: ${form.desired_outcome}`,
  `Contact consent: ${form.contact_consent ? 'yes' : 'no'}`,
  `Source: ${source}`,
  `Received at: ${receivedAt}`
].join('\n');

return {
  json: {
    ...form,
    firstName,
    lastName,
    website: cleanWebsite,
    source,
    receivedAt,
    leadDescription
  }
};
